import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`create-online-course`,heroTitle:`Turn your content into a course`,heroSubtitle:`Perplexity Computer analyzes your social media, extracts your expertise, and builds a complete course curriculum — automatically.`,inputUrlCta:`Build my course`,inputUrlPlaceholder:`Social profile URL`,inputUrlPrefill:`Go to {url} and perform a deep content audit of this social media profile. 1) Analyze all available posts, videos, threads, and content to identify the creator's core expertise, recurring themes, and unique frameworks. 2) Identify the top 5-8 teachable topics based on engagement, depth, and audience demand. 3) Organize these topics into a structured online course curriculum with modules, lessons, and learning objectives — sequenced from beginner to advanced. 4) Write a compelling course title, subtitle, and sales description targeting the creator's existing audience. 5) Generate detailed lesson outlines for each module — including key talking points, exercises, and assignments. 6) Create a course launch checklist with pricing recommendations, platform suggestions (Teachable, Kajabi, Gumroad), and a promotional plan using their existing social channels. 7) Build a lead magnet outline — a free mini-lesson or PDF — to drive signups from their social audience.`,heroOverlaySteps:[`Scanning your social content for expertise and recurring themes`,`Identifying your most teachable topics by depth and engagement`,`Structuring modules, lessons, and learning objectives`,`Complete course curriculum and launch plan — ready to sell`],generatingSteps:[`Visiting {url} to analyze your content, themes, and audience engagement`,`Designing an agent to extract teachable topics and organize them into a curriculum`,`Configuring lesson outlines, exercises, and course sales copy`,`Setting up your launch checklist with pricing, platform, and promotion plan`],featureSectionTitle:`From social posts to sellable course`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can sell`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Sheets, Notion, Canva, Google Drive — Computer delivers your curriculum, lesson outlines, and launch assets straight into the tools you already use.`,`Full course curriculum. Detailed lesson outlines. Sales page copy. Pricing strategy. Lead magnet outline. A launch checklist to go from idea to income.`],capabilitySectionTitle:`Your course creator, on autopilot`,capabilitySectionSubtitle:`Paste your profile, step away, come back to a course ready to launch.`,capabilityCards:[{title:`Expertise Extraction`,description:`Computer can analyze your posts, threads, and videos to identify the unique frameworks and knowledge your audience already pays attention to.`},{title:`Curriculum Design`,description:`Computer can organize your expertise into a structured course — modules, lessons, learning objectives — sequenced from beginner to advanced.`},{title:`Sales Copy`,description:`Computer can write your course title, description, and sales page copy — positioning your knowledge as a product your audience wants to buy.`},{title:`Connect Your Tools`,description:`Computer can push your curriculum into Google Docs, lesson plans into Notion, asset lists into Google Sheets — build workflows across your entire creator stack.`},{title:`Remember & Refine`,description:`Computer can remember your content themes, audience feedback, and past course iterations — so every update sharpens your curriculum.`},{title:`Monitor & Alert`,description:`Computer can track your social content for new high-performing topics and flag when you have enough material for your next module or course.`}]});export{t as default};
